def render_toc_ul(toc: Iterable[Tuple[int, str, str]]) -> str:
    """Render a table of contents as a nested HTML unordered list.

    :param toc: iterable of (level, id, text) tuples
    :returns: HTML string
    """
    if not toc:
        return ''

    toc_list = list(toc)
    if not toc_list:
        return ''

    # Build nested ul structure
    result = []
    first_level = toc_list[0][0]
    current_level = first_level

    result.append('<ul>\n')

    for level, tid, text in toc_list:
        if level > current_level:
            # Need to go deeper
            while current_level < level:
                result.append('<ul>\n')
                current_level += 1
        elif level < current_level:
            # Need to go up
            while current_level > level:
                result.append('</ul>\n')
                current_level -= 1

        result.append(f'<li><a href="#{tid}">{text}</a></li>\n')

    # Close any remaining open lists
    while current_level > first_level:
        result.append('</ul>\n')
        current_level -= 1

    result.append('</ul>\n')

    return ''.join(result)
